<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm('rapports'); $pdo=pdo(); $rev=$pdo->query('SELECT COALESCE(SUM(montant),0) FROM paiements')->fetchColumn(); $top=$pdo->query("SELECT v.marque,v.modele,COUNT(*) nb FROM reservations r JOIN voitures v ON v.id=r.voiture_id GROUP BY v.id ORDER BY nb DESC LIMIT 5")->fetchAll(); $status=$pdo->query("SELECT statut,COUNT(*) nb FROM reservations GROUP BY statut")->fetchAll(); render_header('Rapports'); ?><section class="stats-grid"><?php card('Chiffre encaissé',money($rev),'tous paiements'); card('Contrats',$pdo->query('SELECT COUNT(*) FROM reservations')->fetchColumn(),'réservations'); card('Clients actifs',$pdo->query('SELECT COUNT(DISTINCT client_id) FROM reservations')->fetchColumn(),'ayant loué'); ?></section><section class="grid two"><div class="panel"><h2>Véhicules les plus loués</h2><?php foreach($top as $t):?><div class="list-item"><b><?=e($t['marque'].' '.$t['modele'])?></b><span><?=e($t['nb'])?> location(s)</span></div><?php endforeach;?></div><div class="panel"><h2>Statuts des réservations</h2><?php foreach($status as $s):?><div class="list-item"><b><?=e($s['statut'])?></b><span><?=e($s['nb'])?></span></div><?php endforeach;?></div></section><?php render_footer(); ?>
